  for (const actor of [maya, owner]) { assert.doesNotThrow(() => assertCanChangeOwner(aliceOwned, actor, who("bob"))); assert.doesNotThrow(() => assertCanChangeOwner(aliceOwned, actor, undefined)); assert.doesNotThrow(() => assertCanChangeOwner(unowned, actor, who("carol"))); assert.doesNotThrow(() => assertCanChangeOwner(unowned, actor, who(actor.userId))); }
  for (const state of ["claimed", "running", "unknown"] as const) { const busy = task({ owner: who("alice"), attempts: [attempt(state)] }); refuses(() => assertCanChangeOwner(busy, maya, who("bob")), /Stop the attempt running on laptop before changing the owner/, 409); refuses(() => assertCanChangeOwner(busy, owner, undefined), /Stop the attempt/, 409); refuses(() => assertCanChangeOwner(busy, alice, undefined), /Stop the attempt/, 409); refuses(() => assertCanChangeOwner(busy, vic, who("vic")), /contributor role/, 403, ); assert.doesNotThrow(() => assertCanChangeOwner(busy, maya, who("alice")), "same owner is a no-op even while running"); }
  for (const state of ["paused", "finished", "failed", "stopped", "superseded"] as const) assert.doesNotThrow(() => assertCanChangeOwner(task({ owner: who("alice"), attempts: [attempt(state)] }), maya, who("bob")), state);
  const resumedEarlier = task({ owner: who("alice"), attempts: [attempt("running", { runnerName: "desk" }), attempt("paused", { id: "1".repeat(32), runnerName: "laptop" })] }); refuses(() => assertCanChangeOwner(resumedEarlier, maya, who("bob")), /Stop the attempt running on desk before changing the owner/, 409); refuses(() => assertCanChangeOwner(resumedEarlier, alice, undefined), /running on desk/, 409); assert.doesNotThrow(() => assertCanChangeOwner(resumedEarlier, maya, who("alice")));
  const paused = task({ owner: who("alice"), attempts: [attempt("finished", { id: "1".repeat(32) }), attempt("paused", { id: "2".repeat(32) })] });
  assignOwner(paused, { userId: "bob", displayName: "Bob", via: "browser" }, 50); assert.deepEqual(paused.owner, { userId: "bob", displayName: "Bob", via: "browser" }); assert.equal(paused.attempts[1]!.state, "superseded"); assert.equal(paused.attempts[1]!.endedAt, 50); assert.equal(paused.attempts[0]!.state, "finished"); assert.equal(paused.updatedAt, 50); assert.equal(currentAttempt(paused), undefined);
  const twicePaused = task({ owner: who("alice"), attempts: [attempt("paused", { id: "1".repeat(32) }), attempt("paused", { id: "2".repeat(32) }), attempt("finished", { id: "3".repeat(32) }), attempt("paused", { id: "4".repeat(32) }), attempt("stopped", { id: "5".repeat(32) })] });
  assignOwner(twicePaused, who("bob"), 55); assert.deepEqual(twicePaused.attempts.map((a) => a.state), ["superseded", "superseded", "finished", "superseded", "superseded"], "every paused or stopped attempt is superseded, not only the latest"); assert.deepEqual(twicePaused.attempts.map((a) => a.endedAt), [55, 55, undefined, 55, 55]); assert.equal(currentAttempt(twicePaused), undefined); assert.equal(summarize(twicePaused).attempt, undefined);
  for (const state of ["claimed", "running", "unknown"] as const) { const busy = task({ owner: who("alice"), attempts: [attempt(state), attempt("paused", { id: "1".repeat(32) })] }); refuses(() => assignOwner(busy, who("bob"), 56), /Stop the attempt running on laptop before changing the owner/, 409); assert.equal(busy.owner!.userId, "alice"); assert.equal(busy.attempts[1]!.state, "paused"); assert.equal(busy.updatedAt, 1000); assert.equal(assignOwner(busy, who("alice"), 57).updatedAt, 57, "the same owner is applied even while running"); assert.equal(busy.attempts[1]!.state, "paused"); }
  const unknown = task({ owner: who("alice"), attempts: [attempt("unknown")] }); refuses(() => assignOwner(unknown, undefined, 60), /Stop the attempt/, 409); assert.equal(unknown.owner?.userId, "alice"); assert.equal(unknown.attempts[0]!.state, "unknown");
  const same = task({ owner: who("alice"), attempts: [attempt("paused")] }); assignOwner(same, who("alice"), 70); assert.equal(same.attempts[0]!.state, "paused", "re-assigning the same owner supersedes nothing");
  const finished = task({ owner: who("alice"), attempts: [attempt("finished")] }); assignOwner(finished, who("bob"), 80); assert.equal(finished.attempts[0]!.state, "finished", "terminal attempts are left as history");
  const source = who("carol"); assignOwner(unowned, source, 90); source.displayName = "changed"; assert.equal(unowned.owner!.displayName, "carol", "the task keeps its own copy");
