test("the current attempt is the latest unfinished one and is live only while claimed or running with a heartbeat under 90 s", () => {
  assert.equal(currentAttempt(task()), undefined);
  const attempts = [attempt("finished", { id: "1".repeat(32) }), attempt("paused", { id: "2".repeat(32) }), attempt("running", { id: "3".repeat(32), lastHeartbeatAt: 10_000 }), attempt("failed", { id: "4".repeat(32) })];
  const t = task({ attempts }); assert.equal(currentAttempt(t)!.id, "3".repeat(32));
  assert.equal(currentAttempt(task({ attempts: [attempt("finished"), attempt("unknown", { id: "9".repeat(32) })] }))!.state, "unknown", "unknown counts as current"); assert.equal(currentAttempt(task({ attempts: [attempt("paused")] }))!.state, "paused"); assert.equal(currentAttempt(task({ attempts: [attempt("claimed")] }))!.state, "claimed");
  assert.equal(currentAttempt(task({ attempts: [attempt("superseded"), attempt("stopped"), attempt("failed"), attempt("finished")] })), undefined);
  const resumedEarlier = task({ attempts: [attempt("running", { id: "1".repeat(32), lastHeartbeatAt: 10_000 }), attempt("paused", { id: "2".repeat(32), lastHeartbeatAt: 20_000 })] });
  assert.equal(busyAttempt(resumedEarlier)!.id, "1".repeat(32), "a running attempt is busy wherever it sits"); assert.equal(currentAttempt(resumedEarlier)!.id, "1".repeat(32), "the card follows the attempt that is executing, not the latest paused one"); assert.equal(liveAttempt(resumedEarlier, 10_001)!.id, "1".repeat(32)); assert.equal(liveAttempt(resumedEarlier, 10_000 + MAX.heartbeatLiveMs), undefined);
  assert.equal(busyAttempt(task()), undefined); assert.equal(busyAttempt(task({ attempts: [attempt("paused"), attempt("unknown", { id: "1".repeat(32) })] }))!.state, "unknown"); assert.equal(busyAttempt(t)!.id, "3".repeat(32)); assert.equal(busyAttempt(task({ attempts: [attempt("claimed", { id: "1".repeat(32) }), attempt("running", { id: "2".repeat(32) })] }))!.id, "2".repeat(32), "the latest busy attempt names the runner in refusals");
  const running = attempts[2]!; assert.equal(attemptIsLive(running, 10_000 + MAX.heartbeatLiveMs - 1), true); assert.equal(attemptIsLive(running, 10_000 + MAX.heartbeatLiveMs), false); assert.equal(attemptIsLive(running, 10_000 + MAX.heartbeatLiveMs + 1), false); assert.equal(attemptIsLive(running, 10_000), true);
  assert.equal(attemptIsLive(attempt("claimed", { lastHeartbeatAt: 10_000 }), 10_001), true); for (const state of ["paused", "unknown", "finished", "failed", "stopped", "superseded"] as const) assert.equal(attemptIsLive(attempt(state, { lastHeartbeatAt: 10_000 }), 10_001), false, state);
  assert.equal(attemptIsLive({ state: "running", lastHeartbeatAt: 10_000 }, 99_999), true, "works on the summary's attempt pick too");
  assert.equal(liveAttempt(t, 99_999)!.id, "3".repeat(32)); assert.equal(liveAttempt(t, 100_000), undefined); assert.equal(liveAttempt(task({ attempts: [attempt("paused", { lastHeartbeatAt: 10_000 })] }), 10_001), undefined); assert.equal(liveAttempt(task()), undefined);
  assert.equal(liveAttempt(task({ attempts: [attempt("running", { lastHeartbeatAt: Date.now() })] }))!.state, "running", "defaults to the wall clock");
});

test("review state follows the latest checkpoint: the most recent fresh verdict wins, stale and older-checkpoint reviews are ignored", () => {
  const c1 = checkpoint("1".repeat(32), 100), c2 = checkpoint("2".repeat(32), 200);
  assert.equal(reviewState(task()), "none"); assert.equal(reviewState(task({ reviewer: who("rita") })), "none", "nothing to review yet");
  assert.equal(reviewState(task({ checkpoints: [c1] })), "none"); assert.equal(reviewState(task({ checkpoints: [c1], reviewer: who("rita") })), "pending");
  assert.equal(reviewState(task({ checkpoints: [c1], reviews: [review(c1.id, "approve", 110)] })), "approved"); assert.equal(reviewState(task({ checkpoints: [c1], reviews: [review(c1.id, "request-changes", 110)] })), "changes-requested");
  assert.equal(reviewState(task({ checkpoints: [c1], reviews: [review(c1.id, "approve", 110), review(c1.id, "request-changes", 120)] })), "changes-requested");
  assert.equal(reviewState(task({ checkpoints: [c1], reviews: [review(c1.id, "request-changes", 110), review(c1.id, "approve", 120)] })), "approved");
  assert.equal(reviewState(task({ checkpoints: [c1], reviews: [review(c1.id, "approve", 120), review(c1.id, "request-changes", 110)] })), "approved", "ordered by time, not by array position");
  assert.equal(reviewState(task({ checkpoints: [c1, c2], reviewer: who("rita"), reviews: [review(c1.id, "approve", 110, true)] })), "pending", "an approve of an older checkpoint does not carry over");
  assert.equal(reviewState(task({ checkpoints: [c1, c2], reviews: [review(c1.id, "approve", 110)] })), "none", "a review that points at an older checkpoint never counts, stale flag or not");
  assert.equal(reviewState(task({ checkpoints: [c2, c1], reviews: [review(c1.id, "approve", 110), review(c2.id, "request-changes", 210)] })), "changes-requested", "latest checkpoint by time, not by array order");
  assert.equal(reviewState(task({ checkpoints: [c1], reviews: [review(c1.id, "approve", 110, true)] })), "none", "stale reviews are ignored even on the latest checkpoint");
  assert.equal(reviewState(task({ checkpoints: [c1], reviewer: who("rita"), reviews: [review(c1.id, "request-changes", 110, true), review(c1.id, "approve", 105)] })), "approved");
});

test("summaries carry the card fields, the current attempt, the latest checkpoint and the hand-over, and leak nothing else", () => {
  const c1 = checkpoint("1".repeat(32), 100), c2 = checkpoint("2".repeat(32), 200);
  const t = task({ title: "Ship", goal: "SECRET-GOAL", acceptance: "SECRET-ACCEPTANCE", status: "working", owner: who("alice"), reviewer: who("rita"), collaborators: [who("bob")], dependsOn: ["t-aaaaaaaaaaaaaaaa"], labels: ["bug"], baseRef: "main", revision: 7,
    attempts: [attempt("finished", { id: "1".repeat(32), runnerName: "old-box" }), attempt("running", { id: "3".repeat(32), runnerName: "laptop", lastHeartbeatAt: 500, progress: { updatedAt: 500, stage: "Build", changedFiles: ["a.ts"] }, runId: "SECRET-RUN", reason: "SECRET-REASON" })],
    checkpoints: [c2, c1], reviews: [review(c2.id, "approve", 210)], discussion: [{ id: "c-1", by: who("bob"), text: "SECRET-COMMENT", mentions: ["alice"], at: 1, kind: "comment" }], decisions: [{ id: "d-1", by: who("bob"), text: "SECRET-DECISION", at: 1 }], instructions: [{ id: "i-1", by: who("bob"), text: "SECRET-INSTRUCTION", at: 1, state: "proposed" }],
    handoff: { id: "h-1", from: who("alice"), to: who("bob"), checkpointId: c2.id, note: "SECRET-NOTE", state: "offered", offeredAt: 300 }, handoffs: [{ id: "h-0", from: who("bob"), to: who("alice"), checkpointId: c1.id, note: "SECRET-OLD-NOTE", state: "accepted", offeredAt: 150 }], audit: [{ at: 1, by: who("alice"), action: "SECRET-AUDIT" }] });
  const summary = summarize(t, "alice", 1000, 2);
  assert.deepEqual(summary, { id: TASK, projectId: "p-1", repository: "app", title: "Ship", status: "working", owner: who("alice"), collaborators: [who("bob")], reviewer: who("rita"), dependsOn: ["t-aaaaaaaaaaaaaaaa"], labels: ["bug"], revision: 7, createdAt: 1000, updatedAt: 1000, reviewState: "approved",
    attempt: { id: "3".repeat(32), state: "running", runnerName: "laptop", user: who("alice"), lastHeartbeatAt: 500, progress: { updatedAt: 500, stage: "Build", changedFiles: ["a.ts"] } }, checkpoint: { id: c2.id, commit: HEX40, at: 200 }, handoff: { id: "h-1", to: who("bob"), from: who("alice"), state: "offered" }, unreadMentions: 2 });
  assert.equal(JSON.stringify(summary).includes("SECRET"), false); assert.equal("blocker" in summary, false); assert.equal("goal" in summary, false);
  assert.equal(summarize(t, undefined, 1000, 2).unreadMentions, undefined, "a personal count is attached only when the summary is for a person"); assert.equal(summarize(t, "alice", 1000).unreadMentions, undefined); assert.equal(summarize(t, "alice", 1000, 0).unreadMentions, 0); assert.equal(summarize(t).attempt!.id, "3".repeat(32));
  summary.attempt!.progress.changedFiles!.push("mutated"); summary.labels.push("mutated"); summary.owner!.displayName = "mutated"; summary.collaborators[0]!.displayName = "mutated"; assert.deepEqual(t.attempts[1]!.progress.changedFiles, ["a.ts"]); assert.deepEqual(t.labels, ["bug"]); assert.equal(t.owner!.displayName, "alice"); assert.equal(t.collaborators[0]!.displayName, "bob");
  const bare = summarize(task({ status: "blocked", blocker: "waiting" }), "bob", 1); assert.equal(bare.attempt, undefined); assert.equal(bare.checkpoint, undefined); assert.equal(bare.handoff, undefined); assert.equal(bare.owner, undefined); assert.equal(bare.reviewer, undefined); assert.equal(bare.blocker, "waiting"); assert.equal(bare.reviewState, "none");
  assert.equal(summarize(task({ attempts: [attempt("finished"), attempt("stopped", { id: "1".repeat(32) })] })).attempt, undefined, "terminal attempts are not the card's attempt"); assert.equal(summarize(task({ attempts: [attempt("unknown")] })).attempt!.state, "unknown");
  assert.equal(summarize(task({ attempts: [attempt("running", { id: "1".repeat(32), runnerName: "desk" }), attempt("paused", { id: "2".repeat(32) })] })).attempt!.runnerName, "desk", "a card shows the executing attempt even when a later one is paused");
});

test("bounded lists refuse at their limit, the audit trail drops its oldest entries, and clones never alias the source", () => {
  // Permanent task history has no item-delete UI; the refusal must point to a follow-up task.
  const list = [0, 1, 2]; assert.deepEqual(pushBounded(list, 3, 4, "comments"), [0, 1, 2, 3]); refuses(() => pushBounded(list, 4, 4, "comments"), /At most 4 comments can be kept on this task.*permanent; start a follow-up task/); assert.deepEqual(list, [0, 1, 2, 3]); refuses(() => pushBounded([1, 2, 3, 4, 5], 6, 4, "attempts"), /At most 4 attempts/);
  assert.deepEqual(pushBounded(list, 9, 4, "audit entries", "drop-oldest"), [1, 2, 3, 9]); assert.deepEqual(pushBounded([1, 2, 3, 4, 5, 6], 7, 3, "x", "drop-oldest"), [5, 6, 7]); assert.deepEqual(pushBounded([], 1, 1, "x", "drop-oldest"), [1]); assert.deepEqual(pushBounded([1], 2, 1, "x", "drop-oldest"), [2]);
  const t = task({ audit: Array.from({ length: 205 }, (_, i) => ({ at: i, by: who("alice"), action: `a${i}` })) }); assert.equal(trimAudit(t), t); assert.equal(t.audit.length, 200); assert.equal(t.audit[0]!.at, 5); assert.equal(t.audit[199]!.at, 204); trimAudit(t); assert.equal(t.audit.length, 200);
  for (let i = 0; i < 3; i++) recordAudit(t, { userId: "bob", displayName: "Bob", via: "runner" }, "x".repeat(70), "y".repeat(600), 900 + i);
  assert.equal(t.audit.length, 200); assert.equal(t.audit[0]!.at, 8); const last = t.audit[199]!; assert.equal(last.at, 902); assert.deepEqual(last.by, { userId: "bob", displayName: "Bob" }); assert.equal([...last.action].length, 60); assert.ok(last.action.endsWith("…")); assert.equal([...last.detail!].length, 500);
  const short = recordAudit(task(), who("alice"), "task.created", undefined, 5); assert.deepEqual(short, { at: 5, by: { userId: "alice", displayName: "alice" }, action: "task.created" }); assert.equal("detail" in short, false);
  assert.equal(truncateText("short", 10), "short"); assert.equal(truncateText("🦉🦉🦉🦉", 3), "🦉🦉…"); assert.equal(truncateText("abc", 3), "abc"); assert.equal(truncateText("abcd", 1), "…"); assert.equal(truncateText("", 5), "");
  const original = task({ labels: ["a"], owner: who("alice"), attempts: [attempt("running")] }); const copy = clone(original); copy.labels.push("b"); copy.owner!.displayName = "changed"; copy.attempts[0]!.state = "failed"; assert.deepEqual(original.labels, ["a"]); assert.equal(original.owner!.displayName, "alice"); assert.equal(original.attempts[0]!.state, "running"); assert.notEqual(copy, original); assert.deepEqual(clone(original), original);
});
